 * that map key prefixes to ordered lists of policies, and the sequence of
 * events to replay. Throws a ParseError with a 1-based line number and a
 * short reason string on any malformed input.
 */

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function fail(line, reason) {
  throw new ParseError(line, reason)
}

function parseField(line, token, fieldName, min) {
  if (!INT_RE.test(token) || BigInt(token) < BigInt(min)) {
    fail(line, `${fieldName} must be an integer of at least ${min}`)
  }
  return BigInt(token)
}

export function parseProgram(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const policies = new Map()
  const routes = new Map()
  const events = []
  let hasEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'bucket' || word === 'window' || word === 'route') {
      if (hasEvent) fail(lineNo, 'declarations must come before the first event')
    }

    if (word === 'bucket') {
      const rest = tokens.slice(1)
      if (rest.length !== 4) fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [name, capTok, refillTok, perTok] = rest
      if (!NAME_RE.test(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const capacity = parseField(lineNo, capTok, 'capacity', 1)
      const refill = parseField(lineNo, refillTok, 'refill', 0)
      const per = parseField(lineNo, perTok, 'per', 1)
      policies.set(name, { type: 'bucket', name, capacity, refill, per })
    } else if (word === 'window') {
      const rest = tokens.slice(1)
      if (rest.length !== 3) fail(lineNo, 'expected window <name> <limit> <span>')
      const [name, limitTok, spanTok] = rest
      if (!NAME_RE.test(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const limit = parseField(lineNo, limitTok, 'limit', 0)
      const span = parseField(lineNo, spanTok, 'span', 1)
      policies.set(name, { type: 'window', name, limit, span })
    } else if (word === 'route') {
      const rest = tokens.slice(1)
      if (rest.length < 2) fail(lineNo, 'expected route <prefix> <policy>...')
      const [prefix, ...policyNames] = rest
      if (!NAME_RE.test(prefix)) fail(lineNo, `invalid route prefix ${prefix}`)
      if (routes.has(prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
      for (const pn of policyNames) {
        if (!policies.has(pn)) fail(lineNo, `unknown policy ${pn}`)
      }
      routes.set(prefix, policyNames.map((pn) => policies.get(pn)))
    } else if (word === 'event') {
      const rest = tokens.slice(1)
      if (rest.length !== 2) fail(lineNo, 'expected event <tick> <key>')
      const [tickTok, keyTok] = rest
      const tick = parseField(lineNo, tickTok, 'tick', 0)
      if (!NAME_RE.test(keyTok)) fail(lineNo, `invalid key ${keyTok}`)
      if (lastTick !== null && tick < lastTick) {
        fail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      hasEvent = true
      events.push({ tick, key: keyTok, line: lineNo })
    } else {
      fail(lineNo, `unknown directive ${word}`)
    }
  }

  return { policies, routes, events }
}

export function resolveRoute(routes, key) {
  let best = null
  for (const [prefix, policyList] of routes) {
    if (key.startsWith(prefix)) {
      if (best === null || prefix.length > best.prefix.length) {
        best = { prefix, policyList }
      }
    }
  }
  return best ? best.policyList : []
}
"}

