      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const capacity = parseField(lineNo, capTok, 'capacity', 1)
      const refill = parseField(lineNo, refillTok, 'refill', 0)
      const per = parseField(lineNo, perTok, 'per', 1)
      policies.set(name, { type: 'bucket', name, capacity, refill, per })
    } else if (word === 'window') {
      const rest = tokens.slice(1)
      if (rest.length !== 3) fail(lineNo, 'expected window <name> <limit> <span>')
      const [name, limitTok, spanTok] = rest
      if (!NAME_RE.test(name)) fail(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      const limit = parseField(lineNo, limitTok, 'limit', 0)
      const span = parseField(lineNo, spanTok, 'span', 1)
      policies.set(name, { type: 'window', name, limit, span })
    } else if (word === 'route') {
      const rest = tokens.slice(1)
      if (rest.length < 2) fail(lineNo, 'expected route <prefix> <policy>...')
      const [prefix, ...policyNames] = rest
      if (!NAME_RE.test(prefix)) fail(lineNo, `invalid route prefix ${prefix}`)
      if (routes.has(prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
      for (const pn of policyNames) {
        if (!policies.has(pn)) fail(lineNo, `unknown policy ${pn}`)
      }
      routes.set(prefix, policyNames.map((pn) => policies.get(pn)))
    } else if (word === 'event') {
      const rest = tokens.slice(1)
      if (rest.length !== 2) fail(lineNo, 'expected event <tick> <key>')
      const [tickTok, keyTok] = rest
      const tick = parseField(lineNo, tickTok, 'tick', 0)
      if (!NAME_RE.test(keyTok)) fail(lineNo, `invalid key ${keyTok}`)
      if (lastTick !== null && tick < lastTick) {
        fail(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      hasEvent = true
      events.push({ tick, key: keyTok, line: lineNo })
    } else {
      fail(lineNo, `unknown directive ${word}`)
    }
