function bucketState(policy, key) {
  if (!policy.state) policy.state = new Map()
  let s = policy.state.get(key)
  if (!s) {
    s = { numerator: policy.capacity * policy.per, lastTick: null }
    policy.state.set(key, s)
  }
  return s
}

function windowState(policy, key) {
  if (!policy.state) policy.state = new Map()
  let s = policy.state.get(key)
  if (!s) {
    s = { ticks: [] }
    policy.state.set(key, s)
  }
  return s
}

export function advance(policy, key, tick) {
  if (policy.type === 'bucket') {
    const s = bucketState(policy, key)
    if (s.lastTick === null) {
      s.lastTick = tick
      return
    }
    const elapsed = tick - s.lastTick
    if (elapsed > 0n) {
      const cap = policy.capacity * policy.per
      s.numerator += policy.refill * elapsed
      if (s.numerator > cap) s.numerator = cap
      s.lastTick = tick
    }
  } else {
    const s = windowState(policy, key)
    const threshold = tick - policy.span
    s.ticks = s.ticks.filter((t) => t > threshold)
  }
