/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { parseProgram, resolveRoute, ParseError } from './parser.js'
import { advance, canAllow, record } from './policies.js'

function readStdin() {
  const chunks = []
  const fs = require_fs()
  const fd = 0
  const buf = Buffer.alloc(65536)
  let bytes
  while (true) {
    try {
      bytes = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytes === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytes)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function require_fs() {
  // Small indirection kept so this file reads cleanly top to bottom.
  // eslint-disable-next-line global-require
  return require('node:fs')
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readStdin()

  let program
  try {
    program = parseProgram(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
      return
    }
    throw err
  }

  const lines = []
  const perKey = new Map() // key -> { allowed, denied }
  let totalAllowed = 0n
  let totalDenied = 0n

  for (const ev of program.events) {
    const policyList = resolveRoute(program.routes, ev.key)

    for (const policy of policyList) {
      advance(policy, ev.key, ev.tick)
    }

    let deniedBy = null
    for (const policy of policyList) {
      if (!canAllow(policy, ev.key)) {
        deniedBy = policy.name
        break
      }
    }

    let stats = perKey.get(ev.key)
    if (!stats) {
      stats = { allowed: 0n, denied: 0n }
      perKey.set(ev.key, stats)
    }

    if (deniedBy === null) {
      for (const policy of policyList) {
        record(policy, ev.key, ev.tick)
      }
      stats.allowed += 1n
      totalAllowed += 1n
      if (mode === 'replay') lines.push(`${ev.tick} ${ev.key} allow`)
    } else {
      stats.denied += 1n
      totalDenied += 1n
      if (mode === 'replay') lines.push(`${ev.tick} ${ev.key} deny ${deniedBy}`)
    }
  }

  let output
  if (mode === 'replay') {
    output = lines.map((l) => l + '\n').join('')
  } else {
    const keys = [...perKey.keys()].sort()
    const out = []
    for (const key of keys) {
      const s = perKey.get(key)
      out.push(`${key} allowed=${s.allowed} denied=${s.denied}\n`)
    }
    out.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
    output = out.join('')
  }

  process.stdout.write(output)
  process.exit(0)
}

main()
"}

